import json,hashlib,datetime,copy,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from validate import question_hash,schema_errors,validate_bank
read=lambda p:json.loads((ROOT/p).read_text());sha=lambda p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def write(p,v):(ROOT/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
R='define_robotics_data_contracts:L15-independent-reviewer';now=datetime.datetime.now(datetime.timezone.utc).isoformat();ap='audits/blind-answers-W03-L15-v1-contracts-reviewer.json';assert sha(ap)=='e37b863ea4d1f3078b85c204a1975479f39621ec3a30afb3597cb0221fe4a9d1'
e=read(ap);answers={a['questionId']:a for a in e['answers']};obs={o['physicalPage']:o for o in e['pageObservations']};assert len(answers)==49 and len(obs)==23
for o in obs.values():assert sha(o['previewPath'])==o['previewSha256']
b=read('audits/review-snapshots/W03-L15-v1-contracts.json');reveal=read('audits/W03-L15-contracts-author-reveal.json');assert sha('audits/review-snapshots/W03-L15-v1-contracts.json')==reveal['batchSha256']
flags={}
def flag(n,k,msg):flags.setdefault(f'W03-L15-Q{n:03}',[]).append((k,msg))
flag(4,'distractors','Replace the arbitrary theta1*theta2 multiplication and constant-entry-invalidates-symmetry alternatives with credible dependency errors, such as assuming the entire matrix is constant from M22 alone, or assuming the full matrix depends on theta1 because it appears in gravity. The current source qualification is correct, but the distractors do not meaningfully test it.')
flag(5,'assumptions','The pre-answer assumptions explicitly disclose both requested mass locations: m1 at first-link tip and m2 at second-link tip. Remove those answer-revealing locations from this particular diagram question, keeping only nonrevealing model assumptions, so the learner must inspect the cited diagram rather than copy the assumption. No change to the key is needed.')
flag(6,'explanation','The o4 explanation and copied misconception say [[5,3],[3,3]] comes from treating l2 as1 rather than2. With all other stated parameters unchanged, l2=1 gives [[8,3],[3,3]], because M11=3+5=8. Replace o4 with that coherent distractor or explain the actual combination of omissions that yields its entries. The correct [[17,12],[12,12]] key is independently confirmed.')
flag(17,'sourceSupport','The only citation is page459, which names task quantities but does not establish their power-conjugacy condition or the orientation-rate caveat. Add the actual power/transpose premise, at least page460 with an explicit short derivation from the matching velocity/effort relation; for the orientation-coordinate distinction cite the appropriate earlier source premise if retained. The physical statement is correct, but the present citation does not support its distinguishing condition.')
metadata='The attached three-equation task-transform formula contains qdot but has no qdot variable definition or units, and provides no units for Jdot or the grouped M,V,G symbols. Complete the formula metadata: define the joint-rate vector and its joint-type units, Jdot as the derivative of the same Jacobian with units J per second, and the compatible joint inertia/effort units. Alternatively retain only the equation relevant to this question and fully define its symbols. Formula-sheet entries must be self-contained; correct keys do not repair this shared metadata omission.'
for n in [23,24,25,32,33,34,35]:flag(n,'explanation',metadata)
flag(28,'explanation','The o4 inverse [[1,0],[-2,2]] is not explained by merely failing to normalize the second row by the diagonal2: doubling the correct second row gives[-2,1], not[-2,2]. Replace that distractor with the actual unnormalized row[-2,1], or give a precise rationale accounting for both erroneous entries. Keep the independently verified inverse [[1,0],[-1,1/2]].')
flag(30,'sourceSupport','The answer uses the rotating-frame transport theorem, but pages461 and463 only show the Jacobian differentiation and tool-component matrix; neither states the omega cross velocity term. Add the earlier source transport premise (for example the derivative-of-R-vector identity on physical358) and show v=R v_T differentiation with the common-frame convention. Preserve the correct plus sign and the distinction between component derivative and inertial acceleration.')
flag(32,'explanation','The o3 rationale and copied misconception identify(-24,3) as J^-T V with the Jdot correction omitted. At the stated parameters J=[[1,0],[2,2]], J^-T=[[1,-1],[0,1/2]] and V=(-48,6), so J^-T V=(-54,3), not(-24,3). Change the distractor to(-54,3) or give a different accurate error derivation. The correct Vx=(-54,9) is verified independently.')
flag(34,'sourceSupport','The explanation relies on Gx=J^-T G, but the sole citation is page466, which contains the ambiguous prose and back-transformed torque equation. Add the precise defining premise on page462 (or464) so the correction is supported by both the disputed wording and the actual transformation, not just a whole-page conflict citation.')
flag(35,'distractors','Replace gravity multiplied by joint velocity and point masses becoming configuration-dependent masses with plausible transformation errors: e.g. retaining B,C while dropping Jdot qdot, applying only an effort transformation, or using the wrong correction sign. The correct mechanism is sound, but these alternatives are unrelated to credible coefficient-transform mistakes.')
flag(37,'assumptions','Before answering, neither the stem nor the question assumptions says these are compensating actuator-effort models. The keyed option says the Coulomb sign follows motion, whereas actual friction torque opposes it. The solution discloses the convention only after answering. State the positive compensating-effort convention in the stem/assumptions and distinguish actual resisting torque, as Q038 does.')
for n in [43,45,49]:flag(n,'explanation','This question explicitly includes or discusses friction F, but its attached formula is the ideal no-friction tau=Mqddot+V+G and defines no F. Supply the actual friction-inclusive equation/forward solve with F defined as joint friction effort and its units (and, for Q045, the full first-order state derivative), or remove an unnecessary formula block where the prose is sufficient. The current key is correct, but the displayed revision formula does not cover the question’s stated model.')
reviews=[]
for q in b['questions']:
 a=answers[q['id']];assert question_hash(q)==a['questionSha256'];assert q['correctOptionIds']==a['independentAnswerOptionIds'];assert R not in {q['authorId'],*q.get('revisionAuthors',[])}
 checks={k:True for k in ['sourceSupport','assumptions','answerSet','distractors','calculations','figureFidelity','explanation','difficulty','duplication']}
 for k,_ in flags.get(q['id'],[]):checks[k]=False
 pages=sorted({c['physicalPage'] for c in q['citations']})
 reason=a['reasoning']+' All cited actual source pixels were inspected before the answer freeze, and no L15 author keys, solutions, scripts or findings were read until all49 independent answers and the independent computation script were persisted. After reveal I examined every option rationale, formula, source caveat, units, frames and difficulty. The 29 exact checks and400 random cases independently derive dynamics from point-mass Cartesian kinematics; recall-only items need no numerical calculation. Figure fidelity is grounded in actual diagrams/equations; there are no unverified generated redraws. Distinct definition/application/limiting-case angles are retained, with no duplicate item identified in this49-question batch. '+('The exact remaining defects prevent approval, despite agreement with the intended key.' if q['id'] in flags else 'All nine criteria pass for this version; this is not a claim of complete course coverage.')
 reviews.append(dict(id=q['id']+'-v1-contracts-independent',questionId=q['id'],questionVersion=q['version'],questionSha256=question_hash(q),reviewerId=R,decision='flagged' if q['id'] in flags else 'verified',reviewedAt=now,sourceVersions=e['sourceVersions'],reviewedSlideIds=[f'lectures-p{p:04d}' for p in pages],independentAnswerOptionIds=a['independentAnswerOptionIds'],solvedBeforeAnswerSeen=True,checks=checks,reasoning=reason,findings=[msg for _,msg in flags.get(q['id'],[])],blindAnswersPath=ap,blindAnswersSha256=sha(ap),independentSolvedAt=a['solvedAt'],priorAuthorExposure=False,computationsPath='audits/W03-L15-independent-checks.json',sourceInspectionEvidence=[{k:obs[p][k] for k in ['physicalPage','inspectorId','previewPath','previewSha256','dimensions','inspectedAt']} for p in pages]))
assert len(reviews)==49 and len(flags)==17
errors=[x for r in reviews for x in schema_errors(r,read('data/schema.review.json'))];assert not errors,errors
out='data/reviews/W03-L15-v1-independent-contracts.json';write(out,reviews)
rb={r['questionId']:r for r in reviews};qs=copy.deepcopy(b['questions']);cs=copy.deepcopy(b['concepts'])
for q in qs:q['status']=rb[q['id']]['decision'];q['reviewIds']=[rb[q['id']]['id']]
verified={q['id'] for q in qs if q['status']=='verified'}
for c in cs:c['status']='verified' if any(qid in verified for qid in c['questionIds']) else 'drafted'
manifest=read('sources/manifest.json');slides=[json.loads(s) for sid in ['lectures','assignments'] for s in (ROOT/f'sources/page_maps/{sid}.jsonl').read_text().splitlines()];updates={s['id']:s for s in read('data/inspection-batches/W03-L15.json')['slides']};slides=[copy.deepcopy(updates.get(s['id'],s)) for s in slides]
for s in slides:
 if s['id'] in updates:s['conceptIds']=[c['id'] for c in cs if s['id'] in c['slideIds']]
tmp={'schemaVersion':'1.0.0','bankVersion':'L15-v1-contracts-independent-isolated','title':'L15 independent review validation','complete':False,'sources':manifest['sources'],'assets':manifest['assets'],'slides':slides,'questions':qs,'concepts':cs,'reviews':reviews,'learningTools':{k:[] for k in ['formulaSheet','confusionPairs','traps','algorithmVisualizations','numericalFamilies']}}
v=validate_bank(tmp,ROOT,check_files=True)
coverage=[{'id':'L15-COVERAGE-01','status':'open','sourcePages':[462,464,465,466],'finding':'The only expanded Vx numerical item uses cos(theta2)=0, suppressing both the m2*l1*cos(theta2) and m1*l1*cos(theta2)/sin²(theta2) coefficients. No current item reconstructs the full task force Mx times component acceleration plus Vx plus Gx and then checks its joint effort. Add a meaningful assembled-dynamics question at a nonspecial angle with nonzero rates, explicitly distinguishing the rotating-component derivative; it can test the otherwise suppressed coefficient and the complete transformation together rather than add an arbitrary numeric paraphrase.'},{'id':'L15-COVERAGE-02','status':'bounded_source_notation_note','sourcePages':[462],'finding':'The final Vx definition on physical462 has qddot in its argument label although its expanded RHS depends on q and qdot. Existing questions consistently use qdot; retain this visible source typo in the source-issue ledger instead of silently normalizing it.'}]
summary=dict(reviewerId=R,completedAt=now,questionsReviewed=49,verified=32,flagged=17,keyDisagreements=0,actualPagesInspected=23,reviewFile=out,reviewSha256=sha(out),blindAnswersSha256=sha(ap),independentChecks='audits/W03-L15-independent-checks.json',flaggedQuestionIds=list(flags),findings=[{'questionId':id,'criteria':[k for k,_ in fs],'findings':[msg for _,msg in fs]} for id,fs in flags.items()],coverageChallenge=coverage,validation=v,sourceQualifications='Preserve moving-frame component-derivative scope, square inverse, Gx/G distinction, full mixed-pair enumeration, qualified25% figure and Euler/Taylor naming. Resolution is question-version-bound through the review hashes, not a global correction of the PDF.',mutations='Review/audit/check-script/handoff files only; no author content, canonical bank, source or Git edits.')
write('audits/W03-L15-contracts-review-summary.json',summary)
(ROOT/'docs/handoffs/L15-contracts-review.md').write_text('# L15 independent review frozen\n\n32 verified and17 flagged, with all49 intended keys agreeing with blind answers. All23 actual pages450–472 inspected. Independent source-based math passed29 exact assertions and400 randomized cases.\n\nReview: data/reviews/W03-L15-v1-independent-contracts.json. Exact item flags and coverage challenge: audits/W03-L15-contracts-review-summary.json. Q006 andQ032 contain definite numerical distractor-rationale errors; Q028 has an incoherent unnormalized-row rationale. Shared task-transform metadata omits qdot and derivative units; friction-inclusive questions display a no-friction formula. Additional fixes concern mass-location answer leakage, pre-answer friction-sign convention, weak distractors and missing source premises.\n\nOne meaningful coverage gap remains: assemble full task dynamics at a nonspecial angle with nonzero cosine and rates, retaining the moving-component derivative convention, then recover joint effort. The source462 Vx argument typo should also stay in the ledger.\n\nFrozen blind answers and reveal record preserve chronology; reviewer snapshot is immutable. No author, bank, source or Git edits. Next: independently re-review three L11 v3 repairs, disclosing prior v2 keyed exposure.\n')
print(json.dumps({k:v for k,v in summary.items() if k not in ['findings','coverageChallenge']},indent=2));assert v['valid'],v
